mapper.select:
SELECT g.student_id, g.goal_type, g.direction_id, cd.name AS direction_name, g.name AS goal_name, g.chosen_at, g.updated_at, g.version_no FROM student_goal g LEFT JOIN career_direction cd ON cd.code = g.direction_id WHERE g.student_id IN
#{sid}
AND g.status = 'ACTIVE' ORDER BY g.goal_type

SELECT pt.student_id, COUNT(*) AS total_tasks, SUM(CASE WHEN pt.status = 'DONE' THEN 1 ELSE 0 END) AS done_tasks FROM plan_task pt JOIN semester_plan sp ON sp.id = pt.plan_id AND sp.status = 'CONFIRMED' WHERE pt.student_id IN
#{sid}
GROUP BY pt.student_id

SELECT student_id, MAX(submitted_at) AS last_review_at FROM stage_review WHERE status = 'SUBMITTED' AND student_id IN
#{sid}
GROUP BY student_id

SELECT g.student_id, COUNT(*) AS change_count FROM goal_version gv JOIN student_goal g ON g.id = gv.goal_id WHERE g.student_id IN
#{sid}
AND gv.created_at >= #{since} GROUP BY g.student_id

SELECT id, task_id, done_desc, gains, difficulties, proof_url, checked_in_at FROM task_checkin WHERE task_id IN
#{tid}
ORDER BY checked_in_at ASC
